// Generates src/index.ts from component folders. Each folder exports from its own index.ts.
import { readdirSync, existsSync, writeFileSync, renameSync } from "node:fs";
import { resolve } from "node:path";
const root = resolve(import.meta.dirname, "../src");
const comps = readdirSync(resolve(root, "components"), { withFileTypes: true })
  .filter((d) => d.isDirectory() && existsSync(resolve(root, "components", d.name, "index.ts")))
  .map((d) => d.name).sort();
const lines = [
  "/* Generated by scripts/barrel.mjs — do not edit. */",
  'export * from "./utils/index.js";',
  ...comps.map((c) => `export * from "./components/${c}/index.js";`),
];
const tmp = resolve(root, `index.ts.${process.pid}.tmp`);
writeFileSync(tmp, lines.join("\n") + "\n");
renameSync(tmp, resolve(root, "index.ts"));
console.log(`barrel: ${comps.length} component folders`);
